//! Exact text snapshots and catalog keys for safe table editing.
use super::{literal, required};
use crate::PgSession;
use openrows_driver_api::DriverError;

/// Catalog row identity and columns whose values are generated by `PostgreSQL`.
#[derive(Clone, Debug, Default)]
pub struct RowEditInfo {
    /// Supported non-null unique key columns.
    pub key: Vec<String>,
    /// Generated or always-identity columns.
    pub protected: Vec<String>,
}

impl PgSession {
    /// Discover a simple non-null unique key; views and keyless tables return none.
    /// # Errors
    /// Catalog or connection errors.
    pub async fn row_edit_info(
        &mut self,
        schema: &str,
        table: &str,
    ) -> Result<RowEditInfo, DriverError> {
        let template = include_str!("sql/edit-key.sql");
        let sql = template
            .replace("{schema}", &literal(schema)?)
            .replace("{name}", &literal(table)?);
        let keys = self.text_query(&sql).await?;
        let sql = format!(
            "SELECT a.attname FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid = a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = {} AND c.relname = {} AND (a.attgenerated <> '' OR a.attidentity = 'a') AND NOT a.attisdropped",
            literal(schema)?,
            literal(table)?
        );
        let generated = self.text_query(&sql).await?;
        Ok(RowEditInfo {
            key: keys
                .iter()
                .map(|row| required(row, 0))
                .collect::<Result<_, _>>()?,
            protected: generated
                .iter()
                .map(|row| required(row, 0))
                .collect::<Result<_, _>>()?,
        })
    }

    /// Fetch one complete row as exact `PostgreSQL` text, preserving nulls and precision.
    /// Key names must be obtained from `row_edit_info` by the caller.
    /// # Errors
    /// Missing/ambiguous row identity, invalid names, or server errors.
    pub async fn edit_snapshot(
        &mut self,
        target: (&str, &str),
        keys: &[(String, String)],
    ) -> Result<Vec<(String, Option<String>)>, DriverError> {
        let columns = self.table_columns(target.0, target.1).await?;
        let projection = columns
            .iter()
            .map(|column| Ok(format!("{}::text", identifier(&column.name)?)))
            .collect::<Result<Vec<_>, DriverError>>()?
            .join(", ");
        let predicates = keys
            .iter()
            .map(|(name, value)| Ok(format!("{} = {}", identifier(name)?, literal(value)?)))
            .collect::<Result<Vec<_>, DriverError>>()?
            .join(" AND ");
        if keys.is_empty() {
            return Err(DriverError::Unsupported("A stable key is required".into()));
        }
        let sql = format!(
            "SELECT {projection} FROM {}.{} WHERE {predicates} LIMIT 2",
            identifier(target.0)?,
            identifier(target.1)?
        );
        let mut rows = self.text_query(&sql).await?;
        if rows.len() != 1 {
            return Err(DriverError::Unsupported(
                "The row changed or no longer has a unique identity; reload it".into(),
            ));
        }
        let values = rows.remove(0);
        if values.len() != columns.len() {
            return Err(DriverError::Protocol("Incomplete edit snapshot".into()));
        }
        Ok(columns
            .into_iter()
            .map(|column| column.name)
            .zip(values)
            .collect())
    }
}
fn identifier(name: &str) -> Result<String, DriverError> {
    if name.is_empty() || name.contains('\0') {
        return Err(DriverError::Unsupported("Invalid identifier".into()));
    }
    Ok(format!("\"{}\"", name.replace('"', "\"\"")))
}
